//! The state contract, as a COMPILED example — copy this pattern into a handler.
//!
//! @generated by the emulator core scaffold. Safe to edit or delete; it is emitted once.
//!
//! It pins the state-access contract: a handler reaches the engine through `self`
//! (constructor-injected) and must NEVER construct one. `engine` is the name of a
//! CRATE as well as of the field, so `engine::InMemoryEngine::new()` inside a handler
//! COMPILES — and hands that request a private store that is dropped when it returns.
//! The write looks like it succeeded and the next call sees nothing.

use std::sync::Arc;

/// A probe type owned by this test. `state::<T>()` is keyed by TYPE, so a test can use
/// its own without touching `ComAmazonawsAccountaccessruntimeAwsaccountaccessruntimeState`.
#[derive(Default)]
struct Probe {
    writes: u64,
}

#[tokio::test]
async fn state_written_by_one_request_is_visible_to_the_next() {
    // What `router/src/lib.rs` builds and hands to every handler of this service: a
    // SINGLE shared engine. There is no per-caller isolation — every request observes
    // the same state.
    let engine: Arc<engine::InMemoryEngine> = Arc::new(engine::InMemoryEngine::new());

    // A handler does exactly this, via the engine held on `self` (`self.engine`):
    //     let Some(state) = crate::state::service_state(&*self.engine) else { return Err(..) };
    engine.state::<Probe>().lock().writes += 1;

    // A later request sees the write. This is the whole point.
    assert_eq!(
        engine.state::<Probe>().lock().writes,
        1,
        "state must survive between requests on the shared engine"
    );

    // And the mistake this file exists to prevent: an engine built inside a handler is a
    // PRIVATE store. It compiles, it accepts writes, and nothing else ever sees them.
    let hand_built = engine::InMemoryEngine::new();
    assert_eq!(
        hand_built.state::<Probe>().lock().writes,
        0,
        "a hand-built engine is a private store — never construct one in a handler"
    );
}
